package com.fogofwar.fade;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
public class FadingPlayerPredictorTest {
	private final FadingPlayerPredictor predictor = new FadingPlayerPredictor();
	@Test
	public void velocityUsesLastTwoLocations() {
		assertEquals(new WorldPoint(2, -1, 0), predictor.getVelocity(new WorldPoint(12, 19, 0), new WorldPoint(10, 20, 0)));
		assertEquals(new WorldPoint(0, 0, 0), predictor.getVelocity(new WorldPoint(12, 19, 0), null));
	}
	@Test
	public void nearRenderLimitHonorsEdgeAndRunning() {
		WorldPoint local = new WorldPoint(100, 100, 0);
		assertTrue(predictor.isNearRenderLimit(new WorldPoint(114, 100, 0), local, new WorldPoint(0, 0, 0), 15));
		assertFalse(predictor.isNearRenderLimit(new WorldPoint(112, 100, 0), local, new WorldPoint(1, 0, 0), 15));
		assertTrue(predictor.isNearRenderLimit(new WorldPoint(113, 100, 0), local, new WorldPoint(2, 0, 0), 15));
	}
	@Test
	public void initialLocationMatchesExtrapolationRules() {
		WorldPoint local = new WorldPoint(100, 100, 0);
		assertEquals(new WorldPoint(116, 100, 0), predictor.getInitialFadeLocation(new WorldPoint(114, 100, 0), local, new WorldPoint(1, 0, 0), true, 15, true));
		assertEquals(new WorldPoint(114, 100, 0), predictor.getInitialFadeLocation(new WorldPoint(114, 100, 0), local, new WorldPoint(-1, 0, 0), true, 15, true));
		assertEquals(new WorldPoint(114, 100, 0), predictor.getInitialFadeLocation(new WorldPoint(114, 100, 0), local, new WorldPoint(1, 0, 0), false, 15, true));
	}
}

package com.fogofwar.area;
import com.fogofwar.lifecycle.LifecycleComponent;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.List;
@Singleton
public class AreaExclusionManager extends LifecycleComponent {
	private static final List<ExcludedArea> EXCLUDED_AREAS = List.of(
			new ExcludedArea(2367, 5053, 2432, 5119, 0),			// TzHaar Fight Cave
			new ExcludedArea(2256, 5328, 2286, 5359, 0),			// Inferno
			new ExcludedArea(3500, 5100, 4000, 5440, 0, 1),		// Tombs of Amascut
			new ExcludedArea(3136, 4216, 3366, 4474, 0, 1, 2),	// Theatre of Blood
			new ExcludedArea(2215, 5935, 2325, 6035, 0, 1, 2),	// Hallowed Sepulchre Floor 1
			new ExcludedArea(2475, 5935, 2585, 6035, 0, 1, 2),	// Hallowed Sepulchre Floor 2
			new ExcludedArea(2225, 5795, 2575, 5915, 0, 1, 2),	// Hallowed Sepulchre Floors 3-5
			new ExcludedArea(3150, 5690, 3380, 5770, 0, 1, 2),	// Chambers of Xeric
			new ExcludedArea(3250, 5120, 3370, 5700, 0, 1, 2)	// Chambers of Xeric
	);
	private final Client client;
	@Getter
	private boolean playerInExcludedArea = false;
	@Setter
	private Runnable onTransition;
	@Inject
	public AreaExclusionManager(Client client, EventBus eventBus) {
		super(eventBus);
		this.client = client;
	}
	@Override
	protected void onStart() {
		if (client.getGameState() == GameState.LOGGED_IN) checkArea();
	}
	@Override
	protected void onStop() { setPlayerInExcludedArea(false); }
	@Subscribe
	@SuppressWarnings("unused")
	public void onGameStateChanged(GameStateChanged event) {
		if (event.getGameState() == GameState.LOGGED_IN) checkArea();
		else if (event.getGameState() == GameState.LOADING) setPlayerInExcludedArea(false);
	}
	@Subscribe
	@SuppressWarnings("unused")
	public void onGameTick(GameTick event) { checkArea(); }
	private void checkArea() {
		WorldPoint playerPoint = currentPlayerWorldPoint();
		setPlayerInExcludedArea(playerPoint != null && isExcludedArea(playerPoint));
	}
	private boolean isExcludedArea(WorldPoint playerPoint) {
		for (ExcludedArea area : EXCLUDED_AREAS) { if (area.contains(playerPoint)) return true; }
		return false;
	}
	private void setPlayerInExcludedArea(boolean value) {
		if (playerInExcludedArea == value) return;
		playerInExcludedArea = value;
		if (onTransition != null) onTransition.run();
	}
	private WorldPoint currentPlayerWorldPoint() {
		Player player = client.getLocalPlayer();
		if (player == null) return null;
		LocalPoint localPoint = player.getLocalLocation();
		if (localPoint == null) return null;
		return WorldPoint.fromLocalInstance(client, localPoint);
	}
	static final class ExcludedArea {
		private final int minX;
		private final int minY;
		private final int maxX;
		private final int maxY;
		private final int planeMask;
		ExcludedArea(int minX, int minY, int maxX, int maxY, int... planes) {
			this.minX = minX;
			this.minY = minY;
			this.maxX = maxX;
			this.maxY = maxY;
			int mask = 0;
			for (int plane : planes) { if (plane >= 0 && plane < Integer.SIZE) mask |= 1 << plane; }
			this.planeMask = mask;
		}
		boolean contains(WorldPoint point) {
			int plane = point.getPlane();
			return plane >= 0 && plane < Integer.SIZE && (planeMask & (1 << plane)) != 0 &&
					point.getX() >= minX && point.getX() <= maxX &&
					point.getY() >= minY && point.getY() <= maxY;
		}
	}
}

package com.fogofwar.render;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.Stroke;
import java.awt.geom.Area;
import java.awt.geom.GeneralPath;
public final class FogRender {
	private static final int SAILING_SEA_ALPHA_FLOOR = 16;
	private static final int SAILING_SEA_CACHE_SIZE = 16;
	private static final int[] SAILING_SEA_KEYS = new int[SAILING_SEA_CACHE_SIZE];
	private static final Color[] SAILING_SEA_VALUES = new Color[SAILING_SEA_CACHE_SIZE];
	private static int sailingSeaNext;
	private FogRender() {}
	public static void fill(GeneralPath path, Rectangle bounds, int padding, GeneralPath inner) {
		path.reset();
		path.moveTo(bounds.x - padding, bounds.y - padding);
		path.lineTo(bounds.x + bounds.width + padding, bounds.y - padding);
		path.lineTo(bounds.x + bounds.width + padding, bounds.y + bounds.height + padding);
		path.lineTo(bounds.x - padding, bounds.y + bounds.height + padding);
		path.closePath();
		path.append(inner, false);
	}
	public static void drawBorder(Graphics2D graphics, Shape path, Color color, StrokeCache borderStroke, int thickness) {
		Stroke oldStroke = graphics.getStroke();
		graphics.setColor(color);
		graphics.setStroke(borderStroke.get(thickness));
		graphics.draw(path);
		graphics.setStroke(oldStroke);
	}
	public static Area createDifferenceArea(Shape boundary, Shape innerBoundary) {
		Area area = new Area(boundary);
		area.subtract(new Area(innerBoundary));
		return area;
	}
	public static Color sailingSea(Color colour) {
		int rgb = colour.getRGB();
		for (int i = 0; i < SAILING_SEA_VALUES.length; i++) {
			Color cached = SAILING_SEA_VALUES[i];
			if (cached != null && SAILING_SEA_KEYS[i] == rgb) return cached;
		}
		Color sailingSea = new Color(colour.getRed(), colour.getGreen(), colour.getBlue(), Math.max(SAILING_SEA_ALPHA_FLOOR, colour.getAlpha() / 4));
		SAILING_SEA_KEYS[sailingSeaNext] = rgb;
		SAILING_SEA_VALUES[sailingSeaNext] = sailingSea;
		sailingSeaNext = (sailingSeaNext + 1) % SAILING_SEA_CACHE_SIZE;
		return sailingSea;
	}
	public static final class StrokeCache {
		private BasicStroke stroke;
		private int width = -1;
		public BasicStroke get(int w) {
			if (stroke == null || width != w) {
				stroke = new BasicStroke(w);
				width = w;
			}
			return stroke;
		}
	}
}

package com.fogofwar.render;
import net.runelite.api.Point;
import java.awt.geom.GeneralPath;
import java.util.List;
public final class BoundaryPathBuilder {
	public interface Strategy {
		GeneralPath coverage(GeneralPath path);
		boolean isValid(GeneralPath path);
		GeneralPath fallback(GeneralPath path);
	}
	private BoundaryPathBuilder() {}
	public static GeneralPath build(GeneralPath path, List<Point> points, double arcCenterX, double arcCenterY, double arcRadius, Strategy strategy) {
		GeneralPath result = buildPath(path, points, arcCenterX, arcCenterY, arcRadius, strategy, false);
		if (strategy.isValid(result)) return result;
		result = buildPath(path, points, arcCenterX, arcCenterY, arcRadius, strategy, true);
		if (strategy.isValid(result)) return result;
		return strategy.fallback(result);
	}
	private static GeneralPath buildPath(GeneralPath path, List<Point> points, double arcCenterX, double arcCenterY, double arcRadius, Strategy strategy, boolean reverseArc) {
		int n = points.size();
		int firstVisible = -1;
		int visibleCount = 0;
		for (int i = 0; i < n; i++) {
			if (points.get(i) != null) {
				if (firstVisible == -1) firstVisible = i;
				visibleCount++;
			}
		}
		if (visibleCount == 0) return strategy.coverage(path);
		path.reset();
		if (visibleCount == n) return buildCompletePath(path, points);
		Point first = points.get(firstVisible);
		path.moveTo(first.getX(), first.getY());
		for (int i = 0; i < n; i++) {
			int currentIndex = (firstVisible + i) % n;
			int nextIndex = (firstVisible + i + 1) % n;
			Point p1 = points.get(currentIndex);
			Point p2 = points.get(nextIndex);
			if (p1 == null) continue;
			if (p2 != null) path.lineTo(p2.getX(), p2.getY());
			else {
				int nextVisibleIndex = findNextVisibleIndex(points, currentIndex, n);
				if (nextVisibleIndex != -1) addArcToPath(path, p1, points.get(nextVisibleIndex), arcCenterX, arcCenterY, arcRadius, reverseArc);
			}
		}
		path.closePath();
		return path;
	}
	private static GeneralPath buildCompletePath(GeneralPath path, List<Point> points) {
		Point first = points.get(0);
		path.moveTo(first.getX(), first.getY());
		for (int i = 1; i < points.size(); i++) {
			Point point = points.get(i);
			path.lineTo(point.getX(), point.getY());
		}
		path.closePath();
		return path;
	}
	private static int findNextVisibleIndex(List<Point> points, int currentIndex, int n) {
		for (int i = 2; i < n; i++) {
			int index = (currentIndex + i) % n;
			if (points.get(index) != null) return index;
		}
		return -1;
	}
	private static void addArcToPath(GeneralPath path, Point p1, Point p2, double centerX, double centerY, double radius, boolean reverse) {
		double startAngle = Math.toDegrees(Math.atan2(p1.getY() - centerY, p1.getX() - centerX));
		double endAngle = Math.toDegrees(Math.atan2(p2.getY() - centerY, p2.getX() - centerX));
		double sweep = endAngle - startAngle;
		if (sweep <= -180) { sweep += 360; } else if (sweep > 180) { sweep -= 360; }
		if (reverse) sweep += sweep > 0 ? -360 : 360;
		int numSteps = (int) (Math.abs(sweep) / 10) + 1;
		for (int i = 1; i <= numSteps; i++) {
			double angle = Math.toRadians(startAngle + sweep * i / numSteps);
			path.lineTo((float) (centerX + radius * Math.cos(angle)), (float) (centerY + radius * Math.sin(angle)));
		}
	}
}

package com.fogofwar.render;
import com.fogofwar.lifecycle.LifecycleComponent;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.WorldViewLoaded;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import javax.inject.Inject;
import javax.inject.Singleton;
@Singleton
public class RenderCenterProvider extends LifecycleComponent {
	private final Client client;
	private RenderCenter current;
	private boolean resolved;
	private WorldView topWorldView;
	@Inject
	public RenderCenterProvider(Client client, EventBus eventBus) {
		super(eventBus);
		this.client = client;
	}
	public RenderCenter get() {
		if (!resolved) {
			current = RenderCenter.resolve(client, getTopLevelWorldView());
			resolved = true;
		}
		return current;
	}
	public WorldView getTopLevelWorldView() {
		Player player = client.getLocalPlayer();
		WorldView worldView = player != null ? player.getWorldView() : null;
		if (worldView != null && worldView.isTopLevel()) topWorldView = worldView;
		else if (topWorldView == null) topWorldView = client.getTopLevelWorldView();
		return topWorldView;
	}
	private void clear() {
		current = null;
		resolved = false;
	}
	private void clearAll() {
		clear();
		topWorldView = null;
	}
	@Override
	protected void onStop() { clearAll(); }
	@Subscribe
	@SuppressWarnings("unused")
	public void onBeforeRender(BeforeRender event) { clear(); }
	@Subscribe
	@SuppressWarnings("unused")
	public void onGameStateChanged(GameStateChanged event) {
		if (event.getGameState() != GameState.LOGGED_IN) clearAll();
	}
	@Subscribe
	@SuppressWarnings("unused")
	public void onWorldViewLoaded(WorldViewLoaded event) {
		if (!event.getWorldView().isTopLevel()) return;
		topWorldView = event.getWorldView();
		clear();
	}
}

package com.fogofwar.render.minimap;
import com.fogofwar.config.FogOfWarConfig;
import com.fogofwar.render.FogRender;
import com.fogofwar.render.FogRender.StrokeCache;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.geom.Area;
import java.awt.geom.GeneralPath;
import java.awt.geom.Rectangle2D;
final class MinimapFogMask {
	private final FogOfWarConfig config;
	private final GeneralPath fogFillPath = new GeneralPath(GeneralPath.WIND_EVEN_ODD);
	private final StrokeCache borderStroke = new StrokeCache();
	MinimapFogMask(FogOfWarConfig config) { this.config = config; }
	void renderFog(Graphics2D graphics, Shape minimapClipShape, GeneralPath path) {
		Rectangle2D bounds = minimapClipShape.getBounds2D();
		if (path.contains(bounds)) return;
		Rectangle b = bounds.getBounds();
		FogRender.fill(fogFillPath, b, 1, path);
		graphics.setColor(config.minimapFogColour());
		graphics.fill(fogFillPath);
	}
	void renderFullFog(Graphics2D graphics, Shape minimapClipShape) {
		graphics.setColor(config.minimapFogColour());
		graphics.fill(minimapClipShape);
	}
	void renderBorder(Graphics2D graphics, Shape minimapClipShape, GeneralPath path) {
		if (path.contains(minimapClipShape.getBounds2D())) return;
		FogRender.drawBorder(graphics, path, config.minimapBorderColour(), borderStroke, config.minimapBorderThickness());
	}
	void renderSailingSeaFog(Graphics2D graphics, GeneralPath boundary, GeneralPath innerBoundary) {
		Area area = FogRender.createDifferenceArea(boundary, innerBoundary);
		if (area.isEmpty()) return;
		graphics.setColor(FogRender.sailingSea(config.minimapFogColour()));
		graphics.fill(area);
	}
	void renderSailingSeaBorder(Graphics2D graphics, Shape minimapClipShape, GeneralPath path) {
		if (path.contains(minimapClipShape.getBounds2D())) return;
		FogRender.drawBorder(graphics, path, FogRender.sailingSea(config.minimapBorderColour()), borderStroke, config.minimapBorderThickness());
	}
}

package com.fogofwar.render.minimap;
import com.fogofwar.config.FogDisplayMode;
import com.fogofwar.config.FogOfWarConfig;
import com.fogofwar.render.RenderCenter;
import com.fogofwar.render.RenderCenterProvider;
import com.fogofwar.state.ClientState;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import javax.inject.Inject;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.awt.geom.GeneralPath;
public class MinimapFogOverlay extends Overlay {
	private final FogOfWarConfig config;
	private final ClientState clientState;
	private final RenderCenterProvider renderCenterProvider;
	private final MinimapClipProvider clipProvider;
	private final MinimapRenderBoundary renderBoundary;
	private final MinimapFogMask fogMask;
	@Inject
	public MinimapFogOverlay(Client client, FogOfWarConfig config, ClientState clientState, RenderCenterProvider renderCenterProvider, MinimapClipProvider clipProvider) {
		this.config = config;
		this.clientState = clientState;
		this.renderCenterProvider = renderCenterProvider;
		this.clipProvider = clipProvider;
		this.renderBoundary = new MinimapRenderBoundary(client);
		this.fogMask = new MinimapFogMask(config);
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}
	public void clearCaches() {
		clipProvider.clearCaches();
		renderBoundary.clearCaches();
	}
	@Override
	public Dimension render(Graphics2D graphics) {
		if (clientState.isClientNotReady()) return null;
		FogDisplayMode mode = config.minimapDisplayMode();
		boolean showFog = mode.showsFog();
		boolean showBorder = mode.showsBorder();
		if (!showFog && !showBorder) return null;
		Widget minimap = clipProvider.getMinimapWidget();
		if (minimap == null || minimap.isHidden()) return null;
		RenderCenter rc = renderCenterProvider.get();
		if (rc == null) return null;
		Shape minimapClipShape = clipProvider.getClipShape(minimap);
		Shape oldClip = graphics.getClip();
		graphics.setClip(minimapClipShape);
		try {
			int landRadius = config.landRenderDistance();
			if (rc.isOnWorldEntity()) renderSailingFrame(graphics, showFog, showBorder, rc, minimap, minimapClipShape, landRadius);
			else renderLandFrame(graphics, showFog, showBorder, rc, minimap, minimapClipShape, landRadius);
			return null;
		} finally { graphics.setClip(oldClip); }
	}
	private void renderLandFrame(Graphics2D graphics, boolean showFog, boolean showBorder, RenderCenter rc, Widget minimap, Shape minimapClipShape, int landRadius) {
		GeneralPath landPath = renderBoundary.createLandRenderAreaPath(rc, landRadius, minimap.getBounds());
		if (landPath == null) {
			if (showFog) fogMask.renderFullFog(graphics, minimapClipShape);
			return;
		}
		if (showFog) fogMask.renderFog(graphics, minimapClipShape, landPath);
		if (showBorder) fogMask.renderBorder(graphics, minimapClipShape, landPath);
	}
	private void renderSailingFrame(Graphics2D graphics, boolean showFog, boolean showBorder, RenderCenter rc, Widget minimap, Shape minimapClipShape, int landRadius) {
		int seaRadius = config.sailingRenderDistance();
		GeneralPath seaPath = renderBoundary.createSeaRenderAreaPath(rc, seaRadius, minimap.getBounds());
		if (seaPath == null) {
			if (showFog) fogMask.renderFullFog(graphics, minimapClipShape);
			return;
		}
		GeneralPath landPath = config.showLandAreaWhileSailing() ? renderBoundary.createLandRenderAreaPath(rc, landRadius, minimap.getBounds()) : null;
		if (showFog) {
			fogMask.renderFog(graphics, minimapClipShape, seaPath);
			if (landPath != null) fogMask.renderSailingSeaFog(graphics, seaPath, landPath);
		}
		if (showBorder) {
			fogMask.renderBorder(graphics, minimapClipShape, seaPath);
			if (landPath != null) fogMask.renderSailingSeaBorder(graphics, minimapClipShape, landPath);
		}
	}
}

package com.fogofwar.render.minimap;
import com.fogofwar.render.BoundaryPathBuilder;
import com.fogofwar.render.RenderCenter;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import java.awt.Rectangle;
import java.awt.geom.GeneralPath;
import java.util.ArrayList;
import java.util.List;
final class MinimapRenderBoundary implements BoundaryPathBuilder.Strategy {
	private static final int MINIMAP_RENDER_AREA_PADDING = 1;
	private final Client client;
	private final List<Point> boundaryPoints = new ArrayList<>(128);
	private final PathCache seaRenderAreaPath = new PathCache();
	private final PathCache landRenderAreaPath = new PathCache();
	private Rectangle currentMinimapBounds;
	private Point currentCenterPoint;
	private PathCache currentCache;
	MinimapRenderBoundary(Client client) { this.client = client; }
	void clearCaches() {
		seaRenderAreaPath.clear();
		landRenderAreaPath.clear();
	}
	GeneralPath createSeaRenderAreaPath(RenderCenter rc, int radius, Rectangle minimapBounds) {
		return buildRenderAreaPath(rc, radius, minimapBounds, seaRenderAreaPath);
	}
	GeneralPath createLandRenderAreaPath(RenderCenter rc, int radius, Rectangle minimapBounds) {
		return buildRenderAreaPath(rc, radius, minimapBounds, landRenderAreaPath);
	}
	private GeneralPath buildRenderAreaPath(RenderCenter rc, int radius, Rectangle minimapBounds, PathCache cache) {
		LocalPoint centerLp = rc.snappedCenter();
		WorldPoint centerWp = rc.getSnappedWorldPoint();
		if (centerWp == null) return null;
		currentMinimapBounds = minimapBounds;
		currentCenterPoint = rc.getMinimapCenterPoint();
		currentCache = cache;
		int centerPointX = currentCenterPoint != null ? currentCenterPoint.getX() : Integer.MIN_VALUE;
		int centerPointY = currentCenterPoint != null ? currentCenterPoint.getY() : Integer.MIN_VALUE;
		int yaw = client.getCameraYawTarget();
		double zoom = client.getMinimapZoom();
		if (cache.matches(rc.getWorldView().getId(), centerWp, centerLp, radius, minimapBounds, centerPointX, centerPointY, yaw, zoom)) {
			return cache.lastValid();
		}
		collectBoundaryPoints(rc.getWorldView(), centerWp, centerLp, radius);
		double arcRadius = Math.max(minimapBounds.width, minimapBounds.height) / 2.0 + 1;
		GeneralPath path = BoundaryPathBuilder.build(cache.working(), boundaryPoints, minimapBounds.getCenterX(), minimapBounds.getCenterY(), arcRadius, this);
		return path == cache.working() && isValid(path) ? cache.saveValid(rc.getWorldView().getId(), centerWp, centerLp, radius, minimapBounds, centerPointX, centerPointY, yaw, zoom) : path;
	}
	@Override
	public GeneralPath coverage(GeneralPath path) { return fullMinimapCoveragePath(path); }
	@Override
	public boolean isValid(GeneralPath path) { return currentCenterPoint == null || path.contains(currentCenterPoint.getX(), currentCenterPoint.getY()); }
	@Override
	public GeneralPath fallback(GeneralPath path) { return currentCache.hasLastValid() ? currentCache.lastValid() : path; }
	private Point padRenderAreaPoint(Point point) {
		double cx = currentCenterPoint != null ? currentCenterPoint.getX() : currentMinimapBounds.getCenterX();
		double cy = currentCenterPoint != null ? currentCenterPoint.getY() : currentMinimapBounds.getCenterY();
		double dx = point.getX() - cx;
		double dy = point.getY() - cy;
		double distance = Math.hypot(dx, dy);
		if (distance == 0) return point;
		return new Point((int) Math.round(point.getX() + dx * MINIMAP_RENDER_AREA_PADDING / distance), (int) Math.round(point.getY() + dy * MINIMAP_RENDER_AREA_PADDING / distance));
	}
	private void collectBoundaryPoints(WorldView worldView, WorldPoint center, LocalPoint centerLp, int radius) {
		boundaryPoints.clear();
		int sampleRate = Math.max(1, radius / 12);
		int halfTile = Perspective.LOCAL_HALF_TILE_SIZE;
		addMinimapPoint(worldView, center, centerLp, -radius, -radius, -halfTile, -halfTile);
		for (int x = -radius; x <= radius; x += sampleRate) addMinimapPoint(worldView, center, centerLp, x, -radius, 0, -halfTile);
		addMinimapPoint(worldView, center, centerLp, radius, -radius, halfTile, -halfTile);
		for (int y = -radius; y <= radius; y += sampleRate) addMinimapPoint(worldView, center, centerLp, radius, y, halfTile, 0);
		addMinimapPoint(worldView, center, centerLp, radius, radius, halfTile, halfTile);
		for (int x = radius; x >= -radius; x -= sampleRate) addMinimapPoint(worldView, center, centerLp, x, radius, 0, halfTile);
		addMinimapPoint(worldView, center, centerLp, -radius, radius, -halfTile, halfTile);
		for (int y = radius; y >= -radius; y -= sampleRate) addMinimapPoint(worldView, center, centerLp, -radius, y, -halfTile, 0);
	}
	private void addMinimapPoint(WorldView worldView, WorldPoint centerWp, LocalPoint centerLp, int tileXOffset, int tileYOffset, int xOffset, int yOffset) {
		if (!WorldPoint.isInScene(worldView, centerWp.getX() + tileXOffset, centerWp.getY() + tileYOffset)) {
			boundaryPoints.add(null);
			return;
		}
		int x = centerLp.getX() + tileXOffset * Perspective.LOCAL_TILE_SIZE + xOffset;
		int y = centerLp.getY() + tileYOffset * Perspective.LOCAL_TILE_SIZE + yOffset;
		Point projected = Perspective.localToMinimap(client, new LocalPoint(x, y, worldView), RenderCenter.MINIMAP_PROJECTION_DISTANCE);
		boundaryPoints.add(projected == null ? null : padRenderAreaPoint(projected));
	}
	private GeneralPath fullMinimapCoveragePath(GeneralPath path) {
		Rectangle minimapBounds = currentMinimapBounds;
		path.reset();
		double centerX = minimapBounds.getCenterX();
		double centerY = minimapBounds.getCenterY();
		double radius = Math.max(minimapBounds.width, minimapBounds.height);
		int numSegments = 32;
		for (int i = 0; i < numSegments; i++) {
			double angle = 2 * Math.PI * i / numSegments;
			double x = centerX + radius * Math.cos(angle);
			double y = centerY + radius * Math.sin(angle);
			if (i == 0) path.moveTo(x, y);
			else path.lineTo(x, y);
		}
		path.closePath();
		return path;
	}
	private static final class PathCache {
		private GeneralPath working = new GeneralPath();
		private GeneralPath lastValid = new GeneralPath();
		private boolean valid;
		private int worldViewId, centerWorldX, centerWorldY, centerPlane, centerLocalX, centerLocalY, radius, boundsX, boundsY, boundsW, boundsH, centerPointX, centerPointY, yaw;
		private double zoom;
		private GeneralPath working() { return working; }
		private GeneralPath lastValid() { return lastValid; }
		private boolean hasLastValid() { return lastValid.getCurrentPoint() != null; }
		private boolean matches(int worldViewId, WorldPoint centerWp, LocalPoint centerLp, int radius, Rectangle bounds, int centerPointX, int centerPointY, int yaw, double zoom) {
			return valid
					&& this.worldViewId == worldViewId
					&& centerWorldX == centerWp.getX()
					&& centerWorldY == centerWp.getY()
					&& centerPlane == centerWp.getPlane()
					&& centerLocalX == centerLp.getX()
					&& centerLocalY == centerLp.getY()
					&& this.radius == radius
					&& boundsX == bounds.x
					&& boundsY == bounds.y
					&& boundsW == bounds.width
					&& boundsH == bounds.height
					&& this.centerPointX == centerPointX
					&& this.centerPointY == centerPointY
					&& this.yaw == yaw
					&& Double.compare(this.zoom, zoom) == 0;
		}
		private GeneralPath saveValid(int worldViewId, WorldPoint centerWp, LocalPoint centerLp, int radius, Rectangle bounds, int centerPointX, int centerPointY, int yaw, double zoom) {
			GeneralPath valid = working;
			working = lastValid;
			lastValid = valid;
			working.reset();
			this.valid = true;
			this.worldViewId = worldViewId;
			this.centerWorldX = centerWp.getX();
			this.centerWorldY = centerWp.getY();
			this.centerPlane = centerWp.getPlane();
			this.centerLocalX = centerLp.getX();
			this.centerLocalY = centerLp.getY();
			this.radius = radius;
			this.boundsX = bounds.x;
			this.boundsY = bounds.y;
			this.boundsW = bounds.width;
			this.boundsH = bounds.height;
			this.centerPointX = centerPointX;
			this.centerPointY = centerPointY;
			this.yaw = yaw;
			this.zoom = zoom;
			return lastValid;
		}
		private void clear() {
			working.reset();
			lastValid.reset();
			valid = false;
		}
	}
}

package com.fogofwar.render.minimap;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.geom.Area;
import java.awt.geom.Ellipse2D;
import java.util.Arrays;
import javax.inject.Inject;
import javax.inject.Singleton;
@Singleton
public final class MinimapClipProvider {
	private static final int RESIZED_MINIMAP_CLIP_PADDING = 1;
	private static final int FIXED_MINIMAP_CLIP_PADDING = 3;
	private static final int[] ORB_WIDGETS = {InterfaceID.Orbs.HEALTH_BACKING, InterfaceID.Orbs.PRAYER_BACKING, InterfaceID.Orbs.RUNENERGY_BACKING, InterfaceID.Orbs.SPECENERGY_BACKING, InterfaceID.Orbs.ORB_WORLDMAP};
	private final Client client;
	private final Rectangle[] currentOrbBounds = new Rectangle[ORB_WIDGETS.length];
	private Rectangle cachedMinimapBounds;
	private Shape cachedClipShape;
	private long cachedOrbsHash;
	private boolean cachedResized;
	private Widget probeWidget;
	private Rectangle probeBounds;
	private long probeOrbsHash;
	private int probeCycle = Integer.MIN_VALUE;
	private boolean probeResized;
	@Inject
	public MinimapClipProvider(Client client) { this.client = client; }
	public Widget getMinimapWidget() {
		if (client.isResized()) {
			if (client.getVarbitValue(VarbitID.RESIZABLE_STONE_ARRANGEMENT) == 1) return client.getWidget(InterfaceID.ToplevelPreEoc.MINIMAP);
			return client.getWidget(InterfaceID.ToplevelOsrsStretch.MINIMAP);
		}
		return client.getWidget(InterfaceID.Toplevel.MINIMAP);
	}
	void clearCaches() {
		cachedMinimapBounds = null;
		cachedClipShape = null;
		cachedOrbsHash = 0;
		probeWidget = null;
		probeBounds = null;
		probeOrbsHash = 0;
		probeCycle = Integer.MIN_VALUE;
		Arrays.fill(currentOrbBounds, null);
	}
	public Shape getClipShape(Widget minimapWidget) {
		int cycle = client.getGameCycle();
		Rectangle bounds;
		boolean resized;
		long orbsHash;
		if (probeWidget == minimapWidget && probeCycle == cycle) {
			bounds = probeBounds;
			resized = probeResized;
			orbsHash = probeOrbsHash;
		} else {
			bounds = minimapWidget.getBounds();
			resized = client.isResized();
			orbsHash = collectOrbBoundsAndHash();
			probeWidget = minimapWidget;
			probeBounds = bounds;
			probeResized = resized;
			probeOrbsHash = orbsHash;
			probeCycle = cycle;
		}
		if (cachedClipShape != null && bounds.equals(cachedMinimapBounds) && orbsHash == cachedOrbsHash && resized == cachedResized) return cachedClipShape;
		Area clipArea = createEllipse(bounds, resized ? RESIZED_MINIMAP_CLIP_PADDING : FIXED_MINIMAP_CLIP_PADDING);
		for (Rectangle ob : currentOrbBounds) {
			if (ob == null) continue;
			clipArea.subtract(createEllipse(ob, 0));
		}
		cachedClipShape = clipArea;
		cachedMinimapBounds = new Rectangle(bounds);
		cachedOrbsHash = orbsHash;
		cachedResized = resized;
		return cachedClipShape;
	}
	private static Area createEllipse(Rectangle bounds, int padding) { return new Area(new Ellipse2D.Double(bounds.getX() - padding, bounds.getY() - padding, bounds.getWidth() + padding * 2, bounds.getHeight() + padding * 2)); }
	private long collectOrbBoundsAndHash() {
		long h = 1469598103934665603L;
		for (int i = 0; i < ORB_WIDGETS.length; i++) {
			Widget orb = client.getWidget(ORB_WIDGETS[i]);
			Rectangle b = (orb != null && !orb.isHidden()) ? orb.getBounds() : null;
			currentOrbBounds[i] = b;
			if (b == null) h ^= 0xDEADBEEFL;
			else h ^= ((b.x & 0xFFFFL) << 48) ^ ((b.y & 0xFFFFL) << 32) ^ ((b.width & 0xFFFFL) << 16) ^ (b.height & 0xFFFFL);
			h *= 1099511628211L;
		}
		return h;
	}
}

package com.fogofwar.render;
import com.fogofwar.coord.WorldEntityCoords;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
public final class RenderCenter {
	public static final int MINIMAP_PROJECTION_DISTANCE = 32768;
	@Getter
	private final WorldView worldView;
	@Getter
	private final WorldPoint worldPoint;
	private final LocalPoint snappedCenter;
	@Getter
	private final WorldPoint snappedWorldPoint;
	@Getter
	private final Point canvasCenterPoint;
	@Getter
	private final Point minimapCenterPoint;
	@Getter
	private final boolean onWorldEntity;
	private RenderCenter(Client client, WorldView worldView, WorldPoint worldPoint, LocalPoint localPoint, LocalPoint targetLocalPoint, boolean onWorldEntity) {
		this.worldView = worldView;
		this.worldPoint = worldPoint;
		this.onWorldEntity = onWorldEntity;
		this.snappedCenter = snapCenter(onWorldEntity ? targetLocalPoint : localPoint, worldView);
		this.snappedWorldPoint = WorldPoint.fromLocal(worldView, snappedCenter.getX(), snappedCenter.getY(), worldPoint.getPlane());
		this.canvasCenterPoint = Perspective.localToCanvas(client, snappedCenter, worldPoint.getPlane());
		this.minimapCenterPoint = Perspective.localToMinimap(client, snappedCenter, MINIMAP_PROJECTION_DISTANCE);
	}
	public static RenderCenter resolve(Client client, WorldView topWv) {
		Player p = client.getLocalPlayer();
		if (p == null) return null;
		WorldView pwv = p.getWorldView();
		if (topWv == null) return null;
		if (pwv == null || pwv.isTopLevel()) {
			WorldPoint wp = p.getWorldLocation();
			LocalPoint lp = wp != null ? LocalPoint.fromWorld(topWv, wp) : null;
			if (wp == null || lp == null) return null;
			return new RenderCenter(client, topWv, wp, lp, lp, false);
		}
		WorldEntity we = WorldEntityCoords.getPlayerWorldEntity(p, topWv);
		if (we == null) return null;
		if (!WorldEntityCoords.isShip(we)) {
			WorldEntityCoords.ResolvedPoint point = WorldEntityCoords.resolveTopLevel(p, pwv, topWv, we);
			return point != null ? new RenderCenter(client, topWv, point.worldPoint, point.localPoint, point.localPoint, false) : null;
		}
		LocalPoint boatLp = we.getLocalLocation();
		if (boatLp == null) return null;
		LocalPoint boatTarget = we.getTargetLocation();
		if (boatTarget == null) boatTarget = boatLp;
		WorldPoint boatWp = WorldEntityCoords.toTopLevelWorldPoint(topWv, boatLp);
		return new RenderCenter(client, topWv, boatWp, boatLp, boatTarget, true);
	}
	public LocalPoint snappedCenter() { return snappedCenter; }
	private static LocalPoint snapCenter(LocalPoint lp, WorldView worldView) {
		return new LocalPoint(snapAxis(lp.getX()), snapAxis(lp.getY()), worldView);
	}
	private static int snapAxis(int current) { return (current / Perspective.LOCAL_TILE_SIZE) * Perspective.LOCAL_TILE_SIZE + Perspective.LOCAL_HALF_TILE_SIZE; }
}

package com.fogofwar.render.world;
import com.fogofwar.config.FogDisplayMode;
import com.fogofwar.config.FogOfWarConfig;
import com.fogofwar.render.RenderCenter;
import com.fogofwar.render.RenderCenterProvider;
import com.fogofwar.state.ClientState;
import net.runelite.api.Client;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import javax.inject.Inject;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.geom.GeneralPath;
public class WorldFogOverlay extends Overlay {
	private final Client client;
	private final FogOfWarConfig config;
	private final ClientState clientState;
	private final RenderCenterProvider renderCenterProvider;
	private final Rectangle viewport = new Rectangle();
	private final WorldRenderBoundary renderBoundary;
	private final WorldFogMask fogMask;
	private final ActorCutoutMask actorCutouts;
	@Inject
	public WorldFogOverlay(Client client, FogOfWarConfig config, ClientState clientState, RenderCenterProvider renderCenterProvider, VisibleActorTracker visibleActorTracker) {
		this.client = client;
		this.config = config;
		this.clientState = clientState;
		this.renderCenterProvider = renderCenterProvider;
		this.renderBoundary = new WorldRenderBoundary(client);
		this.fogMask = new WorldFogMask(config);
		this.actorCutouts = new ActorCutoutMask(client, visibleActorTracker);
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}
	public void clearCaches() {
		renderBoundary.clearCaches();
		actorCutouts.clearCaches();
	}
	@Override
	public Dimension render(Graphics2D graphics) {
		if (clientState.isClientNotReady()) return null;
		FogDisplayMode mode = config.worldDisplayMode();
		boolean showFog = mode.showsFog();
		boolean showBorder = mode.showsBorder();
		if (!showFog && !showBorder) return null;
		RenderCenter rc = renderCenterProvider.get();
		if (rc == null) return null;
		boolean useCutouts = showFog && config.actorCutoutLimit().isEnabled();
		if (useCutouts) actorCutouts.beginFrame();
		try {
			renderFrame(graphics, showFog, showBorder, rc);
		} finally {
			if (useCutouts) actorCutouts.endFrame();
		}
		return null;
	}
	private void renderFrame(Graphics2D graphics, boolean showFog, boolean showBorder, RenderCenter rc) {
		WorldView worldView = rc.getWorldView();
		int landRadius = config.landRenderDistance();
		boolean sailing = rc.isOnWorldEntity();
		int plane = rc.getWorldPoint().getPlane();
		setViewportBounds();
		if (sailing) renderSailingFrame(graphics, showFog, showBorder, rc, worldView, plane, landRadius);
		else renderLandFrame(graphics, showFog, showBorder, rc, worldView, plane, landRadius);
	}
	private void renderLandFrame(Graphics2D graphics, boolean showFog, boolean showBorder, RenderCenter rc, WorldView worldView, int plane, int landRadius) {
		LocalPoint landCenter = rc.snappedCenter();
		GeneralPath landBoundary = renderBoundary.createLandRenderAreaBoundary(rc, landRadius, viewport);
		if (landBoundary == null) {
			if (showFog) fogMask.renderFullFog(graphics, viewport);
			return;
		}
		if (showFog) fogMask.renderFog(graphics, viewport, worldView, landBoundary, landCenter, plane, landRadius, actorCutouts);
		if (showBorder) fogMask.renderBorder(graphics, landBoundary);
	}
	private void renderSailingFrame(Graphics2D graphics, boolean showFog, boolean showBorder, RenderCenter rc, WorldView worldView, int plane, int landRadius) {
		int seaRadius = config.sailingRenderDistance();
		LocalPoint center = rc.snappedCenter();
		GeneralPath seaBoundary = renderBoundary.createSeaRenderAreaBoundary(rc, seaRadius, viewport);
		if (seaBoundary == null) {
			if (showFog) fogMask.renderFullFog(graphics, viewport);
			return;
		}
		GeneralPath landBoundary = config.showLandAreaWhileSailing() ? renderBoundary.createLandRenderAreaBoundary(rc, landRadius, viewport) : null;
		if (showFog) {
			fogMask.renderFog(graphics, viewport, worldView, seaBoundary, center, plane, seaRadius, actorCutouts);
			if (landBoundary != null) fogMask.renderSailingSeaFog(graphics, viewport, worldView, seaBoundary, landBoundary, center, plane, landRadius, actorCutouts);
		}
		if (showBorder) {
			fogMask.renderBorder(graphics, seaBoundary);
			if (landBoundary != null) fogMask.renderSailingSeaBorder(graphics, landBoundary);
		}
	}
	private void setViewportBounds() {
		viewport.setBounds(client.getViewportXOffset(), client.getViewportYOffset(), client.getViewportWidth(), client.getViewportHeight());
	}
}

package com.fogofwar.render.world;
import com.fogofwar.render.BoundaryPathBuilder;
import com.fogofwar.render.RenderCenter;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import java.awt.Rectangle;
import java.awt.geom.GeneralPath;
import java.util.ArrayList;
import java.util.List;
final class WorldRenderBoundary implements BoundaryPathBuilder.Strategy {
	private final Client client;
	private final List<Point> boundaryPoints = new ArrayList<>(256);
	private final PathCache seaRenderAreaBoundary = new PathCache();
	private final PathCache landRenderAreaBoundary = new PathCache();
	private Rectangle currentViewport;
	private Point currentCenterPoint;
	WorldRenderBoundary(Client client) { this.client = client; }
	void clearCaches() {
		seaRenderAreaBoundary.clear();
		landRenderAreaBoundary.clear();
	}
	GeneralPath createSeaRenderAreaBoundary(RenderCenter rc, int radius, Rectangle viewport) {
		return buildRenderAreaBoundary(rc, radius, viewport, seaRenderAreaBoundary);
	}
	GeneralPath createLandRenderAreaBoundary(RenderCenter rc, int radius, Rectangle viewport) {
		return buildRenderAreaBoundary(rc, radius, viewport, landRenderAreaBoundary);
	}
	private GeneralPath buildRenderAreaBoundary(RenderCenter rc, int radius, Rectangle viewport, PathCache cache) {
		WorldView worldView = rc.getWorldView();
		LocalPoint centerLp = rc.snappedCenter();
		int plane = rc.getWorldPoint().getPlane();
		if (centerLp == null) return null;
		Point centerPoint = rc.getCanvasCenterPoint();
		if (centerPoint == null) centerPoint = new Point(viewport.x + viewport.width / 2, viewport.y + viewport.height - 1);
		currentViewport = viewport;
		currentCenterPoint = centerPoint;
		if (cache.matches(client, worldView.getId(), centerLp, radius, plane, viewport, centerPoint)) return cache.lastPath();
		boundaryPoints.clear();
		int localRadius = radius * Perspective.LOCAL_TILE_SIZE + Perspective.LOCAL_HALF_TILE_SIZE;
		int sampleCount = radius * 2 + 1;
		int step = localRadius * 2 / sampleCount;
		int minX = centerLp.getX() - localRadius;
		int maxX = centerLp.getX() + localRadius;
		int minY = centerLp.getY() - localRadius;
		int maxY = centerLp.getY() + localRadius;
		for (int i = 0; i < sampleCount; i++) addPoint(worldView, minX + i * step, maxY, plane);
		for (int i = 0; i < sampleCount; i++) addPoint(worldView, maxX, maxY - i * step, plane);
		for (int i = 0; i < sampleCount; i++) addPoint(worldView, maxX - i * step, minY, plane);
		for (int i = 0; i < sampleCount; i++) addPoint(worldView, minX, minY + i * step, plane);
		double arcRadius = Math.max(viewport.width, viewport.height) * 2.0;
		BoundaryPathBuilder.build(cache.working(), boundaryPoints, centerPoint.getX(), centerPoint.getY(), arcRadius, this);
		return cache.save(client, worldView.getId(), centerLp, radius, plane, viewport, centerPoint);
	}
	private void addPoint(WorldView worldView, int localX, int localY, int plane) {
		LocalPoint lp = new LocalPoint(localX, localY, worldView);
		boundaryPoints.add(Perspective.localToCanvas(client, lp, plane));
	}
	@Override
	public GeneralPath coverage(GeneralPath path) { return fallback(path); }
	@Override
	public boolean isValid(GeneralPath path) { return path != null && path.contains(currentCenterPoint.getX(), currentCenterPoint.getY()); }
	@Override
	public GeneralPath fallback(GeneralPath path) { return fullViewportCoveragePath(path); }
	private GeneralPath fullViewportCoveragePath(GeneralPath path) {
		Rectangle viewport = currentViewport;
		path.reset();
		path.moveTo(viewport.x - 1, viewport.y - 1);
		path.lineTo(viewport.x + viewport.width + 1, viewport.y - 1);
		path.lineTo(viewport.x + viewport.width + 1, viewport.y + viewport.height + 1);
		path.lineTo(viewport.x - 1, viewport.y + viewport.height + 1);
		path.closePath();
		return path;
	}
	private static final class PathCache {
		private GeneralPath working = new GeneralPath();
		private GeneralPath lastPath = new GeneralPath();
		private boolean valid;
		private int worldViewId, centerLocalX, centerLocalY, radius, plane, boundsX, boundsY, boundsW, boundsH, centerPointX, centerPointY;
		private int camX, camY, camZ, camPitch, camYaw, scale;
		private GeneralPath working() { return working; }
		private GeneralPath lastPath() { return lastPath; }
		private boolean matches(Client client, int worldViewId, LocalPoint centerLp, int radius, int plane, Rectangle bounds, Point centerPoint) {
			return valid
					&& this.worldViewId == worldViewId
					&& centerLocalX == centerLp.getX()
					&& centerLocalY == centerLp.getY()
					&& this.radius == radius
					&& this.plane == plane
					&& boundsX == bounds.x
					&& boundsY == bounds.y
					&& boundsW == bounds.width
					&& boundsH == bounds.height
					&& centerPointX == centerPoint.getX()
					&& centerPointY == centerPoint.getY()
					&& camX == client.getCameraX()
					&& camY == client.getCameraY()
					&& camZ == client.getCameraZ()
					&& camPitch == client.getCameraPitch()
					&& camYaw == client.getCameraYaw()
					&& scale == client.getScale();
		}
		private GeneralPath save(Client client, int worldViewId, LocalPoint centerLp, int radius, int plane, Rectangle bounds, Point centerPoint) {
			GeneralPath path = working;
			working = lastPath;
			lastPath = path;
			working.reset();
			valid = true;
			this.worldViewId = worldViewId;
			this.centerLocalX = centerLp.getX();
			this.centerLocalY = centerLp.getY();
			this.radius = radius;
			this.plane = plane;
			this.boundsX = bounds.x;
			this.boundsY = bounds.y;
			this.boundsW = bounds.width;
			this.boundsH = bounds.height;
			this.centerPointX = centerPoint.getX();
			this.centerPointY = centerPoint.getY();
			this.camX = client.getCameraX();
			this.camY = client.getCameraY();
			this.camZ = client.getCameraZ();
			this.camPitch = client.getCameraPitch();
			this.camYaw = client.getCameraYaw();
			this.scale = client.getScale();
			return lastPath;
		}
		private void clear() {
			working.reset();
			lastPath.reset();
			valid = false;
		}
	}
}

package com.fogofwar.render.world;
import com.fogofwar.lifecycle.LifecycleComponent;
import lombok.Getter;
import net.runelite.api.Actor;
import net.runelite.api.Renderable;
import net.runelite.api.events.BeforeRender;
import net.runelite.client.callback.RenderCallback;
import net.runelite.client.callback.RenderCallbackManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Set;
@Singleton
public class VisibleActorTracker extends LifecycleComponent implements RenderCallback {
	private final RenderCallbackManager renderCallbackManager;
	@Getter
	private final Set<Actor> visibleActors = Collections.newSetFromMap(new IdentityHashMap<>(256));
	@Inject
	public VisibleActorTracker(EventBus eventBus, RenderCallbackManager renderCallbackManager) {
		super(eventBus);
		this.renderCallbackManager = renderCallbackManager;
	}
	@Override
	protected void onStart() { renderCallbackManager.register(this); }
	@Override
	protected void onStop() {
		renderCallbackManager.unregister(this);
		visibleActors.clear();
	}
	@Subscribe
	@SuppressWarnings("unused")
	public void onBeforeRender(BeforeRender event) { visibleActors.clear(); }
	@Override
	public boolean addEntity(Renderable renderable, boolean ui) {
		if (!ui && renderable instanceof Actor) visibleActors.add((Actor) renderable);
		return true;
	}
}

package com.fogofwar.render.world;
import com.fogofwar.coord.WorldEntityCoords;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.geom.Area;
import java.awt.geom.GeneralPath;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import java.util.Set;
final class ActorCutoutMask {
	private static final int ACTOR_CUTOUT_BUCKET_SIZE = 48;
	private static final int PRIORITY_SCORE = Integer.MIN_VALUE / 2;
	private static final Comparator<ActorCutoutCandidate> ACTOR_CUTOUT_CANDIDATE_ORDER = (a, b) -> {
		int c = Integer.compare(a.score, b.score);
		if (c != 0) return c;
		c = Boolean.compare(!a.hit, !b.hit);
		if (c != 0) return c;
		c = Integer.compare(b.canvasY, a.canvasY);
		if (c != 0) return c;
		c = Integer.compare(a.canvasX, b.canvasX);
		if (c != 0) return c;
		c = Integer.compare(a.worldPoint.getX(), b.worldPoint.getX());
		if (c != 0) return c;
		return Integer.compare(a.worldPoint.getY(), b.worldPoint.getY());
	};
	private final Client client;
	private final VisibleActorTracker visibleActorTracker;
	private final ActorHullCache hullCache = new ActorHullCache();
	private final List<ActorCutoutCandidate> exclusionCandidates = new ArrayList<>(256);
	private boolean[] usedBuckets = new boolean[0];
	private Rectangle viewport;
	private Player localPlayer;
	private int exclusionCandidateCount;
	private int lastCamX, lastCamY, lastCamZ, lastCamPitch, lastCamYaw, lastScale, lastVpX, lastVpY, lastVpW, lastVpH;
	private boolean retainHullCache;
	ActorCutoutMask(Client client, VisibleActorTracker visibleActorTracker) {
		this.client = client;
		this.visibleActorTracker = visibleActorTracker;
	}
	void clearCaches() { hullCache.clear(); }
	void beginFrame() {
		updateCameraState();
		hullCache.beginFrame();
		retainHullCache = false;
	}
	void endFrame() {
		if (retainHullCache) hullCache.retainSeen();
	}
	void subtractExclusions(Area fogArea, Rectangle viewport, WorldView worldView, GeneralPath boundary, LocalPoint centerLp, int plane, int radius, int limit) {
		this.viewport = viewport;
		this.localPlayer = client.getLocalPlayer();
		retainHullCache = true;
		Set<Actor> visibleActors = visibleActorTracker.getVisibleActors();
		boolean all = limit == Integer.MAX_VALUE;
		int visibleCount = visibleActors.size();
		boolean ranked = !all && visibleCount + (localPlayer != null && !visibleActors.contains(localPlayer) ? 1 : 0) > limit;
		int bucketColumns = all ? 1 : Math.max(1, (viewport.width + ACTOR_CUTOUT_BUCKET_SIZE - 1) / ACTOR_CUTOUT_BUCKET_SIZE);
		try {
			collectExclusionCandidates(visibleActors, worldView, boundary, centerLp, plane, radius, ranked, bucketColumns);
			if (exclusionCandidateCount == 0) return;
			if (all || !ranked || exclusionCandidateCount <= limit) subtractAllExclusionAreas(fogArea, boundary);
			else {
				exclusionCandidates.subList(0, exclusionCandidateCount).sort(ACTOR_CUTOUT_CANDIDATE_ORDER);
				subtractSelectedExclusionAreas(fogArea, boundary, limit, bucketColumns);
			}
		} finally {
			clearExclusionCandidates();
			this.localPlayer = null;
		}
	}
	private void updateCameraState() {
		lastCamX = client.getCameraX();
		lastCamY = client.getCameraY();
		lastCamZ = client.getCameraZ();
		lastCamPitch = client.getCameraPitch();
		lastCamYaw = client.getCameraYaw();
		lastScale = client.getScale();
		lastVpX = client.getViewportXOffset();
		lastVpY = client.getViewportYOffset();
		lastVpW = client.getViewportWidth();
		lastVpH = client.getViewportHeight();
	}
	private void subtractAllExclusionAreas(Area fogArea, GeneralPath boundary) {
		for (int i = 0; i < exclusionCandidateCount; i++) {
			Area entryArea = getCandidateArea(exclusionCandidates.get(i), boundary);
			if (entryArea == null) continue;
			fogArea.subtract(entryArea);
		}
	}
	private void collectExclusionCandidates(Set<Actor> visibleActors, WorldView worldView, GeneralPath boundary, LocalPoint centerLp, int plane, int radius, boolean ranked, int bucketColumns) {
		exclusionCandidateCount = 0;
		int localRadius = radius * Perspective.LOCAL_TILE_SIZE + Perspective.LOCAL_HALF_TILE_SIZE;
		if (localPlayer != null) collectExclusionCandidate(localPlayer, worldView, boundary, centerLp, plane, localRadius, ranked, bucketColumns);
		for (Actor actor : visibleActors) {
			if (actor == localPlayer) continue;
			collectExclusionCandidate(actor, worldView, boundary, centerLp, plane, localRadius, ranked, bucketColumns);
		}
	}
	private void collectExclusionCandidate(Actor actor, WorldView worldView, GeneralPath boundary, LocalPoint centerLp, int plane, int localRadius, boolean ranked, int bucketColumns) {
		if (actor == null) return;
		boolean priority = actor == localPlayer;
		WorldEntityCoords.ResolvedPoint location = WorldEntityCoords.resolveTopLevel(actor, worldView);
		if (location == null || location.worldPoint.getPlane() != plane) return;
		LocalPoint lp = location.localPoint;
		WorldView actorWv = actor.getWorldView();
		boolean onSubWorld = actorWv != null && !actorWv.isTopLevel();
		ActorHullCache.Entry cached = hullCache.get(actor);
		hullCache.markSeen(actor);
		int anim = actor.getAnimation(), frame = actor.getAnimationFrame();
		int pose = actor.getPoseAnimation(), poseFrame = actor.getPoseAnimationFrame();
		boolean hit = cached != null
				&& cached.wx == location.worldPoint.getX() && cached.wy == location.worldPoint.getY() && cached.plane == location.worldPoint.getPlane()
				&& cached.localX == lp.getX() && cached.localY == lp.getY()
				&& cached.anim == anim && cached.frame == frame
				&& cached.pose == pose && cached.poseFrame == poseFrame
				&& cached.camX == lastCamX && cached.camY == lastCamY && cached.camZ == lastCamZ
				&& cached.camPitch == lastCamPitch && cached.camYaw == lastCamYaw
				&& cached.scale == lastScale
				&& cached.vpX == lastVpX && cached.vpY == lastVpY && cached.vpW == lastVpW && cached.vpH == lastVpH;
		if (hit) {
			if (!viewport.intersects(cached.bounds)) return;
			if (!priority) {
				boolean inside = boundary.contains(cached.bounds);
				if (inside) return;
			}
		}
		int localX, localY, canvasX, canvasY, edgeDistance = 0;
		if (hit) {
			localX = cached.localX;
			localY = cached.localY;
			canvasX = cached.canvasX;
			canvasY = cached.canvasY;
		} else {
			localX = lp.getX();
			localY = lp.getY();
			edgeDistance = getEdgeDistance(localX, localY, centerLp, localRadius);
			int footprintRadius = Math.max(Perspective.LOCAL_TILE_SIZE, actor.getFootprintSize() * Perspective.LOCAL_TILE_SIZE / 2);
			if (!priority && !onSubWorld && edgeDistance < -footprintRadius) return;
			Point canvasPoint = Perspective.localToCanvas(client, lp, plane);
			if (!priority && (canvasPoint == null || !viewport.contains(canvasPoint.getX(), canvasPoint.getY()))) return;
			canvasX = canvasPoint != null ? canvasPoint.getX() : viewport.x + viewport.width / 2;
			canvasY = canvasPoint != null ? canvasPoint.getY() : viewport.y + viewport.height / 2;
		}
		int bucket = -1, score = 0;
		if (ranked) {
			if (viewport.contains(canvasX, canvasY)) bucket = getExclusionBucket(canvasX, canvasY, bucketColumns);
			if (hit) edgeDistance = getEdgeDistance(localX, localY, centerLp, localRadius);
			score = getCandidateScore(actor, hit, edgeDistance);
		}
		addExclusionCandidate(actor, cached, location.worldPoint, anim, frame, pose, poseFrame, hit, score, bucket, canvasX, canvasY, localX, localY);
	}
	private int getEdgeDistance(int localX, int localY, LocalPoint centerLp, int localRadius) {
		int dx = Math.abs(localX - centerLp.getX());
		int dy = Math.abs(localY - centerLp.getY());
		return Math.max(dx, dy) - localRadius;
	}
	private int getCandidateScore(Actor actor, boolean hit, int edgeDistance) {
		if (actor == localPlayer) return PRIORITY_SCORE;
		int score = Math.abs(edgeDistance);
		if (edgeDistance < 0) score += Perspective.LOCAL_TILE_SIZE;
		if (!(actor instanceof Player)) score += Perspective.LOCAL_TILE_SIZE / 2;
		if (hit) score -= Perspective.LOCAL_TILE_SIZE * 8;
		return score;
	}
	private int getExclusionBucket(int canvasX, int canvasY, int bucketColumns) {
		int x = (canvasX - viewport.x) / ACTOR_CUTOUT_BUCKET_SIZE;
		int y = (canvasY - viewport.y) / ACTOR_CUTOUT_BUCKET_SIZE;
		return y * bucketColumns + x;
	}
	private void addExclusionCandidate(Actor actor, ActorHullCache.Entry cached, WorldPoint awp, int anim, int frame, int pose, int poseFrame, boolean hit, int score, int bucket, int canvasX, int canvasY, int localX, int localY) {
		if (exclusionCandidateCount == exclusionCandidates.size()) exclusionCandidates.add(new ActorCutoutCandidate());
		exclusionCandidates.get(exclusionCandidateCount++).set(actor, cached, awp, anim, frame, pose, poseFrame, hit, score, bucket, canvasX, canvasY, localX, localY);
	}
	private void subtractSelectedExclusionAreas(Area fogArea, GeneralPath boundary, int limit, int bucketColumns) {
		int bucketRows = Math.max(1, (viewport.height + ACTOR_CUTOUT_BUCKET_SIZE - 1) / ACTOR_CUTOUT_BUCKET_SIZE);
		int bucketCount = bucketColumns * bucketRows;
		if (usedBuckets.length < bucketCount) usedBuckets = new boolean[bucketCount];
		else Arrays.fill(usedBuckets, 0, bucketCount, false);
		int selected = subtractPriorityExclusionAreas(fogArea, boundary, limit);
		for (int pass = 0; pass < 2 && selected < limit; pass++) {
			for (int i = 0; i < exclusionCandidateCount && selected < limit; i++) {
				ActorCutoutCandidate candidate = exclusionCandidates.get(i);
				if (candidate.selected) continue;
				if (pass == 0 && candidate.bucket < 0) continue;
				if (pass == 0 && usedBuckets[candidate.bucket]) continue;
				Area entryArea = getCandidateArea(candidate, boundary);
				if (entryArea == null) continue;
				candidate.selected = true;
				if (candidate.bucket >= 0) usedBuckets[candidate.bucket] = true;
				fogArea.subtract(entryArea);
				selected++;
			}
		}
	}
	private int subtractPriorityExclusionAreas(Area fogArea, GeneralPath boundary, int limit) {
		int selected = 0;
		for (int i = 0; i < exclusionCandidateCount && selected < limit; i++) {
			ActorCutoutCandidate candidate = exclusionCandidates.get(i);
			if (candidate.actor != localPlayer) continue;
			Area entryArea = getCandidateArea(candidate, boundary);
			if (entryArea != null) {
				candidate.selected = true;
				fogArea.subtract(entryArea);
				selected++;
			}
			break;
		}
		return selected;
	}
	private void clearExclusionCandidates() {
		for (int i = 0; i < exclusionCandidateCount; i++) exclusionCandidates.get(i).clear();
		exclusionCandidateCount = 0;
	}
	private Area getCandidateArea(ActorCutoutCandidate candidate, GeneralPath boundary) {
		Shape hull = getCandidateHull(candidate, boundary);
		if (hull == null) return null;
		ActorHullCache.Entry cached = candidate.cached;
		if (cached == null) return null;
		if (cached.area == null) cached.area = new Area(hull);
		return cached.area;
	}
	private Shape getCandidateHull(ActorCutoutCandidate candidate, GeneralPath boundary) {
		ActorHullCache.Entry cached = candidate.cached;
		if (candidate.hit) return cached.hull;
		Shape hull = candidate.actor.getConvexHull();
		if (hull == null) {
			if (cached != null) hullCache.remove(candidate.actor);
			return null;
		}
		Rectangle bounds = hull.getBounds();
		cache(candidate, hull, bounds);
		if (!viewport.intersects(bounds)) return null;
		if (candidate.actor != localPlayer) {
			boolean inside = boundary.contains(bounds);
			if (inside) return null;
		}
		return hull;
	}
	private void cache(ActorCutoutCandidate candidate, Shape hull, Rectangle bounds) {
		ActorHullCache.Entry cached = hullCache.getOrCreate(candidate.actor);
		candidate.cached = cached;
		cached.hull = hull;
		cached.bounds = bounds;
		cached.area = null;
		cached.wx = candidate.worldPoint.getX();
		cached.wy = candidate.worldPoint.getY();
		cached.plane = candidate.worldPoint.getPlane();
		cached.localX = candidate.localX;
		cached.localY = candidate.localY;
		cached.canvasX = candidate.canvasX;
		cached.canvasY = candidate.canvasY;
		cached.anim = candidate.anim;
		cached.frame = candidate.frame;
		cached.pose = candidate.pose;
		cached.poseFrame = candidate.poseFrame;
		cached.camX = lastCamX;
		cached.camY = lastCamY;
		cached.camZ = lastCamZ;
		cached.camPitch = lastCamPitch;
		cached.camYaw = lastCamYaw;
		cached.scale = lastScale;
		cached.vpX = lastVpX;
		cached.vpY = lastVpY;
		cached.vpW = lastVpW;
		cached.vpH = lastVpH;
	}
	private static final class ActorCutoutCandidate {
		private Actor actor;
		private ActorHullCache.Entry cached;
		private WorldPoint worldPoint;
		private int anim, frame, pose, poseFrame, score, bucket, canvasX, canvasY, localX, localY;
		private boolean hit, selected;
		private void set(Actor actor, ActorHullCache.Entry cached, WorldPoint worldPoint, int anim, int frame, int pose, int poseFrame, boolean hit, int score, int bucket, int canvasX, int canvasY, int localX, int localY) {
			this.actor = actor;
			this.cached = cached;
			this.worldPoint = worldPoint;
			this.anim = anim;
			this.frame = frame;
			this.pose = pose;
			this.poseFrame = poseFrame;
			this.hit = hit;
			this.score = score;
			this.bucket = bucket;
			this.canvasX = canvasX;
			this.canvasY = canvasY;
			this.localX = localX;
			this.localY = localY;
			this.selected = false;
		}
		private void clear() {
			actor = null;
			cached = null;
			worldPoint = null;
			anim = frame = pose = poseFrame = score = bucket = canvasX = canvasY = localX = localY = 0;
			hit = selected = false;
		}
	}
}

package com.fogofwar.render.world;
import com.fogofwar.config.ActorCutoutLimit;
import com.fogofwar.config.FogOfWarConfig;
import com.fogofwar.render.FogRender;
import com.fogofwar.render.FogRender.StrokeCache;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.geom.Area;
import java.awt.geom.GeneralPath;
final class WorldFogMask {
	private final FogOfWarConfig config;
	private final GeneralPath fogPath = new GeneralPath(GeneralPath.WIND_EVEN_ODD);
	private final StrokeCache borderStroke = new StrokeCache();
	WorldFogMask(FogOfWarConfig config) { this.config = config; }
	void renderFog(Graphics2D graphics, Rectangle viewport, WorldView worldView, GeneralPath boundary, LocalPoint centerLp, int plane, int radius, ActorCutoutMask actorCutouts) {
		if (boundary.contains(viewport)) return;
		FogRender.fill(fogPath, viewport, 0, boundary);
		graphics.setColor(config.worldFogColour());
		ActorCutoutLimit cutoutLimit = config.actorCutoutLimit();
		if (!cutoutLimit.isEnabled()) {
			graphics.fill(fogPath);
			return;
		}
		Area fogArea = new Area(fogPath);
		actorCutouts.subtractExclusions(fogArea, viewport, worldView, boundary, centerLp, plane, radius, cutoutLimit.getLimit());
		graphics.fill(fogArea);
	}
	void renderFullFog(Graphics2D graphics, Rectangle viewport) {
		graphics.setColor(config.worldFogColour());
		graphics.fill(viewport);
	}
	void renderBorder(Graphics2D graphics, GeneralPath boundary) {
		FogRender.drawBorder(graphics, boundary, config.worldBorderColour(), borderStroke, config.worldBorderThickness());
	}
	void renderSailingSeaFog(Graphics2D graphics, Rectangle viewport, WorldView worldView, GeneralPath boundary, GeneralPath innerBoundary, LocalPoint centerLp, int plane, int radius, ActorCutoutMask actorCutouts) {
		Area area = FogRender.createDifferenceArea(boundary, innerBoundary);
		if (area.isEmpty()) return;
		ActorCutoutLimit cutoutLimit = config.actorCutoutLimit();
		if (cutoutLimit.isEnabled()) actorCutouts.subtractExclusions(area, viewport, worldView, innerBoundary, centerLp, plane, radius, cutoutLimit.getLimit());
		if (area.isEmpty()) return;
		graphics.setColor(FogRender.sailingSea(config.worldFogColour()));
		graphics.fill(area);
	}
	void renderSailingSeaBorder(Graphics2D graphics, GeneralPath boundary) {
		FogRender.drawBorder(graphics, boundary, FogRender.sailingSea(config.worldBorderColour()), borderStroke, config.worldBorderThickness());
	}
}

package com.fogofwar.render.world;
import net.runelite.api.Actor;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.geom.Area;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Map;
import java.util.Set;
final class ActorHullCache {
	private final Map<Actor, Entry> entries = new IdentityHashMap<>();
	private final Set<Actor> seen = Collections.newSetFromMap(new IdentityHashMap<>(256));
	void clear() {
		entries.clear();
		seen.clear();
	}
	void beginFrame() { seen.clear(); }
	void markSeen(Actor actor) { seen.add(actor); }
	Entry get(Actor actor) { return entries.get(actor); }
	Entry getOrCreate(Actor actor) { return entries.computeIfAbsent(actor, a -> new Entry()); }
	void remove(Actor actor) { entries.remove(actor); }
	void retainSeen() { entries.keySet().retainAll(seen); }
	static final class Entry {
		Shape hull;
		Area area;
		Rectangle bounds;
		int wx, wy, plane, anim, frame, pose, poseFrame;
		int localX, localY, canvasX, canvasY;
		int camX, camY, camZ, camPitch, camYaw, scale, vpX, vpY, vpW, vpH;
	}
}

