package com.fogofwar.config;
public enum FogDisplayMode {
	OFF(false, false, "Off"),
	FOG(true, false, "Fog"),
	BORDER(false, true, "Border"),
	BOTH(true, true, "Fog + border");
	private final boolean fog;
	private final boolean border;
	private final String name;
	FogDisplayMode(boolean fog, boolean border, String name) {
		this.fog = fog;
		this.border = border;
		this.name = name;
	}
	public boolean showsFog() { return fog; }
	public boolean showsBorder() { return border; }
	public boolean isEnabled() { return fog || border; }
	@Override
	public String toString() { return name; }
}

package com.fogofwar.lifecycle;
import net.runelite.client.eventbus.EventBus;
public abstract class LifecycleComponent {
	private final EventBus eventBus;
	private boolean started;
	protected LifecycleComponent(EventBus eventBus) { this.eventBus = eventBus; }
	public final void start() {
		if (started) return;
		eventBus.register(this);
		started = true;
		onStart();
	}
	public final void stop() {
		if (!started) return;
		eventBus.unregister(this);
		started = false;
		onStop();
	}
	protected void onStart() {}
	protected void onStop() {}
}

package com.fogofwar.fade;
import net.runelite.api.coords.WorldPoint;
final class FadingPlayerPredictor {
	WorldPoint getVelocity(WorldPoint lastLocation, WorldPoint twoTicksAgoLocation) {
		return twoTicksAgoLocation != null
				? new WorldPoint(lastLocation.getX() - twoTicksAgoLocation.getX(), lastLocation.getY() - twoTicksAgoLocation.getY(), 0)
				: new WorldPoint(0, 0, 0);
	}
	boolean isNearRenderLimit(WorldPoint lastLocation, WorldPoint localPlayerLocation, WorldPoint velocity, int renderDistance) {
		return isAtRenderLimit(lastLocation, localPlayerLocation, renderDistance) || isRunningNearLimit(lastLocation, localPlayerLocation, velocity, renderDistance);
	}
	WorldPoint getInitialFadeLocation(WorldPoint lastLocation, WorldPoint localPlayerLocation, WorldPoint velocity, boolean extrapolate, int renderDistance, boolean nearRenderLimit) {
		if (!extrapolate) return lastLocation;
		int dx = lastLocation.getX() - localPlayerLocation.getX();
		int dy = lastLocation.getY() - localPlayerLocation.getY();
		boolean onXEdge = Math.abs(dx) >= renderDistance - 1;
		boolean onYEdge = Math.abs(dy) >= renderDistance - 1;
		WorldPoint predictedNextLocation = new WorldPoint(lastLocation.getX() + velocity.getX(), lastLocation.getY() + velocity.getY(), lastLocation.getPlane());
		boolean isMovingIntoRenderArea = (onXEdge && dx * velocity.getX() < 0) || (onYEdge && dy * velocity.getY() < 0);
		if (isMovingIntoRenderArea) {
			int pushX = onXEdge ? Integer.signum(dx) : 0;
			int pushY = onYEdge ? Integer.signum(dy) : 0;
			return new WorldPoint(predictedNextLocation.getX() + pushX, predictedNextLocation.getY() + pushY, predictedNextLocation.getPlane());
		}
		WorldPoint initialFadeLocation = predictedNextLocation;
		if (nearRenderLimit) {
			int pushX = 0, pushY = 0;
			if (Math.abs(dx) > Math.abs(dy)) pushX = Integer.signum(dx);
			else if (Math.abs(dy) > Math.abs(dx)) pushY = Integer.signum(dy);
			else { pushX = Integer.signum(dx); pushY = Integer.signum(dy); }
			if ((pushX != 0 || pushY != 0) && predictedNextLocation.getPlane() == localPlayerLocation.getPlane()) {
				int x = predictedNextLocation.getX();
				int y = predictedNextLocation.getY();
				int lx = localPlayerLocation.getX();
				int ly = localPlayerLocation.getY();
				boolean moved = false;
				while (Math.max(Math.abs(x - lx), Math.abs(y - ly)) <= renderDistance) {
					x += pushX;
					y += pushY;
					moved = true;
				}
				if (moved) initialFadeLocation = new WorldPoint(x, y, predictedNextLocation.getPlane());
			}
		}
		return initialFadeLocation;
	}
	private boolean isAtRenderLimit(WorldPoint lastLocation, WorldPoint localPlayerLocation, int renderDistance) {
		return lastLocation.distanceTo(localPlayerLocation) >= renderDistance - 1;
	}
	private boolean isRunningNearLimit(WorldPoint lastLocation, WorldPoint localPlayerLocation, WorldPoint velocity, int renderDistance) {
		int velocityMagnitude = Math.abs(velocity.getX()) + Math.abs(velocity.getY());
		return lastLocation.distanceTo(localPlayerLocation) >= renderDistance - 2 && velocityMagnitude >= 2;
	}
}

package com.fogofwar.fade;
import com.fogofwar.config.FogOfWarConfig;
import com.fogofwar.area.AreaExclusionManager;
import com.fogofwar.coord.WorldEntityCoords;
import com.fogofwar.lifecycle.LifecycleComponent;
import com.fogofwar.render.RenderCenterProvider;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
@Singleton
public class FadingPlayerManager extends LifecycleComponent {
	private final Client client;
	private final FogOfWarConfig config;
	private final AreaExclusionManager areaExclusionManager;
	private final RenderCenterProvider renderCenterProvider;
	@Getter
	private final Map<Player, FadingPlayer> fadingPlayers = new HashMap<>();
	private Map<Player, TrackedPlayer> lastTickPlayerLocations = new HashMap<>();
	private Map<Player, TrackedPlayer> twoTicksAgoPlayerLocations = new HashMap<>();
	private Map<Player, TrackedPlayer> currentPlayerLocations = new HashMap<>();
	private final Set<String> currentPlayerNames = new HashSet<>();
	private final FadingPlayerPredictor predictor = new FadingPlayerPredictor();
	@Inject
	public FadingPlayerManager(Client client, FogOfWarConfig config, EventBus eventBus, AreaExclusionManager areaExclusionManager, RenderCenterProvider renderCenterProvider) {
		super(eventBus);
		this.client = client;
		this.config = config;
		this.areaExclusionManager = areaExclusionManager;
		this.renderCenterProvider = renderCenterProvider;
	}
	@Override
	protected void onStop() { clearAllTracking(); }
	@Subscribe
	@SuppressWarnings("unused")
	public void onGameStateChanged(GameStateChanged event) {
		if (event.getGameState() == GameState.LOADING) clearAllTracking();
	}
	@Subscribe
	@SuppressWarnings("unused")
	public void onGameTick(GameTick event) {
		if (client.getGameState() != GameState.LOGGED_IN) {
			clearAllTracking();
			return;
		}
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null) {
			clearAllTracking();
			return;
		}
		WorldView worldView = renderCenterProvider.getTopLevelWorldView();
		if (worldView == null) {
			clearAllTracking();
			return;
		}
		WorldPoint localPlayerLocation = WorldEntityCoords.playerToTopLevel(localPlayer, null, worldView);
		if (localPlayerLocation == null) {
			clearAllTracking();
			return;
		}
		if (areaExclusionManager.isPlayerInExcludedArea()) {
			clearAllTracking();
			return;
		}
		boolean onWorldEntity = WorldEntityCoords.isPlayerOnShip(localPlayer, worldView);
		if (config.disableWhileSailing() && onWorldEntity) {
			clearAllTracking();
			return;
		}
		int fadeDuration = config.fadeDurationTicks();
		boolean extrapolate = config.predictMovement();
		boolean onlyAtLimit = config.onlyFadeAtRenderEdge();
		handleFadingPlayers(fadeDuration, extrapolate, localPlayerLocation);
		updatePlayerTracking(extrapolate, onlyAtLimit, localPlayer, worldView, localPlayerLocation, onWorldEntity);
	}
	private void clearAllTracking() {
		fadingPlayers.clear();
		lastTickPlayerLocations.clear();
		twoTicksAgoPlayerLocations.clear();
		currentPlayerLocations.clear();
		currentPlayerNames.clear();
	}
	private void handleFadingPlayers(int fadeDuration, boolean extrapolate, WorldPoint localPlayerLocation) {
		fadingPlayers.entrySet().removeIf(entry -> {
			FadingPlayer fp = entry.getValue();
			fp.setTicksSinceDisappeared(fp.getTicksSinceDisappeared() + 1);
			if (fp.getTicksSinceDisappeared() >= fadeDuration) return true;
			WorldPoint markerLocation = fp.getMarkerLocation();
			if (fp.getTicksSinceDisappeared() > 1 && markerLocation.distanceTo(localPlayerLocation) <= fp.getRenderDistance()) return true;
			WorldPoint velocity = fp.getVelocity();
			if (extrapolate && velocity != null) {
				fp.setMarkerLocation(new WorldPoint(
						markerLocation.getX() + velocity.getX(),
						markerLocation.getY() + velocity.getY(),
						markerLocation.getPlane()));
			}
			return false;
		});
	}
	private void updatePlayerTracking(boolean extrapolate, boolean onlyAtLimit, Player localPlayer, WorldView worldView, WorldPoint localPlayerLocation, boolean onWorldEntity) {
		currentPlayerLocations.clear();
		currentPlayerNames.clear();
		trackPlayers(localPlayer, worldView, worldView, config.landRenderDistance());
		int boatRenderDistance = onWorldEntity ? config.sailingRenderDistance() : config.landRenderDistance();
		for (WorldEntity worldEntity : worldView.worldEntities()) {
			if (worldEntity == null) continue;
			WorldView entityWorldView = worldEntity.getWorldView();
			if (entityWorldView == null) continue;
			trackPlayers(localPlayer, entityWorldView, worldView, boatRenderDistance);
		}
		for (Map.Entry<Player, TrackedPlayer> entry : lastTickPlayerLocations.entrySet()) {
			Player player = entry.getKey();
			if (currentPlayerLocations.containsKey(player)) continue;
			if (fadingPlayers.containsKey(player)) continue;
			TrackedPlayer lastTickPlayer = entry.getValue();
			WorldPoint lastLocation = lastTickPlayer.getLocation();
			if (lastLocation == null) continue;
			int renderDistance = lastTickPlayer.getRenderDistance();
			boolean needsVelocity = onlyAtLimit || extrapolate;
			WorldPoint velocity = null;
			boolean nearRenderLimit = false;
			if (needsVelocity) {
				TrackedPlayer twoTicksAgoPlayer = twoTicksAgoPlayerLocations.get(player);
				WorldPoint twoTicksAgoLocation = twoTicksAgoPlayer != null ? twoTicksAgoPlayer.getLocation() : null;
				velocity = predictor.getVelocity(lastLocation, twoTicksAgoLocation);
				nearRenderLimit = predictor.isNearRenderLimit(lastLocation, localPlayerLocation, velocity, renderDistance);
			}
			if (onlyAtLimit && !nearRenderLimit) continue;
			WorldPoint initialFadeLocation = extrapolate ? predictor.getInitialFadeLocation(lastLocation, localPlayerLocation, velocity, true, renderDistance, nearRenderLimit) : lastLocation;
			fadingPlayers.put(player, new FadingPlayer(player, velocity, initialFadeLocation, renderDistance));
		}
		Map<Player, TrackedPlayer> tmp = twoTicksAgoPlayerLocations;
		twoTicksAgoPlayerLocations = lastTickPlayerLocations;
		lastTickPlayerLocations = currentPlayerLocations;
		currentPlayerLocations = tmp;
		fadingPlayers.entrySet().removeIf(entry -> {
			String name = entry.getKey().getName();
			return name != null && currentPlayerNames.contains(name);
		});
	}
	private void trackPlayers(Player localPlayer, WorldView worldView, WorldView topWorldView, int renderDistance) {
		for (Player player : worldView.players()) {
			if (player == null || player == localPlayer) continue;
			WorldPoint playerLocation = WorldEntityCoords.playerToTopLevel(player, worldView, topWorldView);
			if (playerLocation != null) currentPlayerLocations.put(player, new TrackedPlayer(playerLocation, renderDistance));
			if (player.getName() != null) currentPlayerNames.add(player.getName());
		}
	}
	@Getter
	private static class TrackedPlayer {
		private final WorldPoint location;
		private final int renderDistance;
		private TrackedPlayer(WorldPoint location, int renderDistance) {
			this.location = location;
			this.renderDistance = renderDistance;
		}
	}
}

package com.fogofwar.fade;
import com.fogofwar.config.FogOfWarConfig;
import com.fogofwar.render.RenderCenterProvider;
import com.fogofwar.state.ClientState;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayUtil;
import javax.inject.Inject;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Polygon;
public class FadingPlayerOverlay extends AbstractFadingPlayerOverlay {
	@Inject
	protected FadingPlayerOverlay(Client client, FogOfWarConfig config, FadingPlayerManager manager, ClientState clientState, RenderCenterProvider renderCenterProvider) {
		super(client, config, manager, clientState, renderCenterProvider, OverlayLayer.ABOVE_SCENE);
	}
	@Override
	boolean showsMarker() { return config.playerFadeMarkerMode().showsWorld(); }
	@Override
	void renderPlayer(Graphics2D graphics, WorldView wv, LocalPoint lp, FadingPlayer fadingPlayer) {
		Polygon poly = Perspective.getCanvasTilePoly(client, lp);
		if (poly == null) return;
		Color color = fadingPlayer.getColor(config);
		graphics.setColor(color);
		graphics.fill(poly);
		if (config.showFadeMarkerNames()) {
			String name = fadingPlayer.getPlayer().getName();
			if (name != null) {
				Point textLoc = Perspective.getCanvasTextLocation(client, graphics, lp, name, 0);
				if (textLoc != null) OverlayUtil.renderTextLocation(graphics, textLoc, name, color);
			}
		}
	}
}

package com.fogofwar.fade;
import com.fogofwar.config.FogOfWarConfig;
import com.fogofwar.render.RenderCenterProvider;
import com.fogofwar.render.minimap.MinimapClipProvider;
import com.fogofwar.state.ClientState;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.OverlayLayer;
import javax.inject.Inject;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.util.Collection;
public class FadingPlayerMinimapOverlay extends AbstractFadingPlayerOverlay {
	private static final int DOT_SIZE = 4;
	private final MinimapClipProvider clipProvider;
	@Inject
	protected FadingPlayerMinimapOverlay(Client client, FogOfWarConfig config, ClientState clientState, FadingPlayerManager manager, MinimapClipProvider clipProvider, RenderCenterProvider renderCenterProvider) {
		super(client, config, manager, clientState, renderCenterProvider, OverlayLayer.ABOVE_WIDGETS);
		this.clipProvider = clipProvider;
	}
	@Override
	boolean showsMarker() { return config.playerFadeMarkerMode().showsMinimap(); }
	@Override
	Dimension renderPlayers(Graphics2D graphics, WorldView wv, Collection<FadingPlayer> fadingPlayers) {
		Widget minimapWidget = clipProvider.getMinimapWidget();
		if (minimapWidget == null || minimapWidget.isHidden()) return null;
		Shape oldClip = graphics.getClip();
		graphics.setClip(clipProvider.getClipShape(minimapWidget));
		try {
			return super.renderPlayers(graphics, wv, fadingPlayers);
		} finally { graphics.setClip(oldClip); }
	}
	@Override
	void renderPlayer(Graphics2D graphics, WorldView wv, LocalPoint lp, FadingPlayer fadingPlayer) {
		Point mp = Perspective.localToMinimap(client, lp);
		if (mp == null) return;
		Color color = fadingPlayer.getColor(config);
		Color shadedColor = fadingPlayer.getDarkerColor(config);
		int x = mp.getX() - DOT_SIZE / 2;
		int y = mp.getY() - DOT_SIZE / 2 + 1;
		graphics.setColor(shadedColor);
		graphics.fillArc(x, y, DOT_SIZE, DOT_SIZE, 180, 180);
		graphics.setColor(color);
		graphics.fillArc(x, y, DOT_SIZE, DOT_SIZE, 0, 180);
	}
}

package com.fogofwar.fade;
import com.fogofwar.config.FogOfWarConfig;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import java.awt.Color;
@Getter
class FadingPlayer {
	private final Player player;
	@Setter
	private WorldPoint markerLocation;
	private final WorldPoint velocity;
	private final int renderDistance;
	@Setter
	private int ticksSinceDisappeared = 0;
	private int cachedTick = Integer.MIN_VALUE;
	private int cachedFadeDuration = Integer.MIN_VALUE;
	private int cachedBaseRgb;
	private Color cachedColor;
	private Color cachedDarkerColor;
	FadingPlayer(Player player, WorldPoint velocity, WorldPoint initialLocation, int renderDistance) {
		this.player = player;
		this.velocity = velocity;
		this.markerLocation = initialLocation;
		this.renderDistance = renderDistance;
	}
	Color getColor(FogOfWarConfig config) {
		Color base = config.fadeMarkerColour();
		int duration = config.fadeDurationTicks();
		int baseRgb = base.getRGB();
		if (cachedColor != null && cachedTick == ticksSinceDisappeared && cachedFadeDuration == duration && cachedBaseRgb == baseRgb) return cachedColor;
		float d = Math.max(1, duration);
		float o = (d - ticksSinceDisappeared) / d;
		cachedColor = new Color(base.getRed() / 255f, base.getGreen() / 255f, base.getBlue() / 255f, (base.getAlpha() / 255f) * o);
		cachedDarkerColor = null;
		cachedTick = ticksSinceDisappeared;
		cachedFadeDuration = duration;
		cachedBaseRgb = baseRgb;
		return cachedColor;
	}
	Color getDarkerColor(FogOfWarConfig config) {
		getColor(config);
		if (cachedDarkerColor == null) cachedDarkerColor = cachedColor.darker();
		return cachedDarkerColor;
	}
}

package com.fogofwar.fade;
import com.fogofwar.config.FogOfWarConfig;
import com.fogofwar.render.RenderCenter;
import com.fogofwar.render.RenderCenterProvider;
import com.fogofwar.state.ClientState;
import net.runelite.api.Client;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.Collection;
abstract class AbstractFadingPlayerOverlay extends Overlay {
	protected final Client client;
	protected final FogOfWarConfig config;
	private final FadingPlayerManager manager;
	private final ClientState clientState;
	private final RenderCenterProvider renderCenterProvider;
	AbstractFadingPlayerOverlay(Client client, FogOfWarConfig config, FadingPlayerManager manager, ClientState clientState, RenderCenterProvider renderCenterProvider, OverlayLayer layer) {
		this.client = client;
		this.config = config;
		this.manager = manager;
		this.clientState = clientState;
		this.renderCenterProvider = renderCenterProvider;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_HIGH);
		setLayer(layer);
	}
	@Override
	public Dimension render(Graphics2D graphics) {
		if (!showsMarker() || clientState.isClientNotReady()) return null;
		Collection<FadingPlayer> fadingPlayers = manager.getFadingPlayers().values();
		if (fadingPlayers.isEmpty()) return null;
		RenderCenter rc = renderCenterProvider.get();
		if (rc == null) return null;
		WorldView wv = rc.getWorldView();
		return renderPlayers(graphics, wv, fadingPlayers);
	}
	Dimension renderPlayers(Graphics2D graphics, WorldView wv, Collection<FadingPlayer> fadingPlayers) {
		for (FadingPlayer fadingPlayer : fadingPlayers) renderPlayer(graphics, wv, fadingPlayer);
		return null;
	}
	private void renderPlayer(Graphics2D graphics, WorldView wv, FadingPlayer fadingPlayer) {
		WorldPoint wp = fadingPlayer.getMarkerLocation();
		LocalPoint lp = LocalPoint.fromWorld(wv, wp);
		if (lp == null) return;
		renderPlayer(graphics, wv, lp, fadingPlayer);
	}
	abstract boolean showsMarker();
	abstract void renderPlayer(Graphics2D graphics, WorldView wv, LocalPoint lp, FadingPlayer fadingPlayer);
}

package com.fogofwar;
import com.fogofwar.config.FadingPlayerMode;
import com.fogofwar.config.FogDisplayMode;
import com.fogofwar.config.FogOfWarConfig;
import com.fogofwar.config.FogOfWarConfigMigration;
import com.fogofwar.debug.DebugOverlay;
import com.fogofwar.fade.FadingPlayerManager;
import com.fogofwar.fade.FadingPlayerMinimapOverlay;
import com.fogofwar.fade.FadingPlayerOverlay;
import com.fogofwar.lifecycle.LifecycleComponent;
import com.fogofwar.area.AreaExclusionManager;
import com.fogofwar.render.RenderCenterProvider;
import com.fogofwar.render.minimap.MinimapFogOverlay;
import com.fogofwar.render.world.WorldFogOverlay;
import com.fogofwar.render.world.VisibleActorTracker;
import com.fogofwar.state.ClientState;
import com.google.inject.Provides;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayManager;
import javax.inject.Inject;
import java.util.List;
import java.util.function.Predicate;
@PluginDescriptor(
		name = "Fog of War",
		description = "Applies a fog of war effect outside of the player render distance, in both the world and on the minimap.",
		configName = "FogOfWarPlugin"
)
public class FogOfWarPlugin extends Plugin {
	private static final String CONFIG_GROUP = FogOfWarConfigMigration.CONFIG_GROUP;
	@Inject
	private FogOfWarConfig config;
	@Inject
	private ClientThread clientThread;
	@Inject
	private ClientState clientState;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private WorldFogOverlay worldOverlay;
	@Inject
	private MinimapFogOverlay minimapOverlay;
	@Inject
	private FadingPlayerManager fadingPlayerManager;
	@Inject
	private FadingPlayerOverlay fadingPlayerOverlay;
	@Inject
	private FadingPlayerMinimapOverlay fadingPlayerMinimapOverlay;
	@Inject
	private AreaExclusionManager areaExclusionManager;
	@Inject
	private RenderCenterProvider renderCenterProvider;
	@Inject
	private VisibleActorTracker visibleActorTracker;
	@Inject
	private DebugOverlay debugOverlay;
	private List<ToggleSpec> overlayToggles = List.of();
	private List<LifecycleSpec> lifecycleComponents = List.of();
	private volatile boolean started;
	@Override
	protected void startUp() {
		started = true;
		initComponents();
		areaExclusionManager.setOnTransition(this::updateComponentsOnClientThread);
		updateComponentsOnClientThread();
	}
	@Override
	protected void shutDown() {
		areaExclusionManager.setOnTransition(null);
		started = false;
		for (ToggleSpec overlayToggle : overlayToggles) overlayToggle.disable();
		worldOverlay.clearCaches();
		minimapOverlay.clearCaches();
		for (LifecycleSpec component : lifecycleComponents) component.stop();
	}
	private void initComponents() {
		overlayToggles = List.of(
				new ToggleSpec(worldOverlay, state -> state.worldActive),
				new ToggleSpec(minimapOverlay, state -> state.minimapActive),
				new ToggleSpec(debugOverlay, state -> state.debugActive),
				new ToggleSpec(fadingPlayerOverlay, state -> state.fadingWorldActive),
				new ToggleSpec(fadingPlayerMinimapOverlay, state -> state.fadingMinimapActive));
		lifecycleComponents = List.of(
				new LifecycleSpec(areaExclusionManager, state -> state.anyConfigured),
				new LifecycleSpec(renderCenterProvider, state -> state.overlayActive || state.debugActive),
				new LifecycleSpec(fadingPlayerManager, state -> state.fadingActive),
				new LifecycleSpec(visibleActorTracker, state -> state.visibleActorTrackingActive));
	}
	@Subscribe
	@SuppressWarnings("unused")
	public void onConfigChanged(ConfigChanged event) {
		if (!CONFIG_GROUP.equals(event.getGroup())) return;
		updateComponentsOnClientThread();
	}
	@Subscribe
	@SuppressWarnings("unused")
	public void onGameStateChanged(GameStateChanged event) { updateComponents(); }
	@Subscribe
	@SuppressWarnings("unused")
	public void onVarbitChanged(VarbitChanged event) {
		int id = event.getVarbitId();
		if (id == VarbitID.SAILING_BOARDED_BOAT) {
			if (config.disableWhileSailing()) updateComponents();
			return;
		}
		if (!config.onlyInWilderness() || id != VarbitID.INSIDE_WILDERNESS) return;
		updateComponents();
	}
	private void updateComponents() {
		if (!started) return;
		updateComponents(clientState.isSailing());
	}
	private void updateComponents(boolean sailing) {
		if (!started) return;
		ComponentState state = createComponentState(sailing);
		for (ToggleSpec overlayToggle : overlayToggles) overlayToggle.update(state);
		for (LifecycleSpec component : lifecycleComponents) component.update(state);
	}
	private void updateComponentsOnClientThread() { clientThread.invokeLater((Runnable) this::updateComponents); }
	private ComponentState createComponentState(boolean sailing) {
		FogDisplayMode worldMode = config.worldDisplayMode();
		FogDisplayMode minimapMode = config.minimapDisplayMode();
		FadingPlayerMode fadingPlayerMode = config.playerFadeMarkerMode();
		boolean worldConfigured = worldMode.isEnabled();
		boolean minimapConfigured = minimapMode.isEnabled();
		boolean fadingWorldConfigured = fadingPlayerMode.showsWorld();
		boolean fadingMinimapConfigured = fadingPlayerMode.showsMinimap();
		boolean anyConfigured = worldConfigured || minimapConfigured || fadingWorldConfigured || fadingMinimapConfigured;
		boolean areaEnabled = isCurrentAreaEnabled(sailing);
		boolean worldActive = areaEnabled && worldConfigured;
		boolean minimapActive = areaEnabled && minimapConfigured;
		boolean fadingWorldActive = areaEnabled && fadingWorldConfigured;
		boolean fadingMinimapActive = areaEnabled && fadingMinimapConfigured;
		boolean fadingActive = fadingWorldActive || fadingMinimapActive;
		boolean overlayActive = worldActive || minimapActive || fadingActive;
		boolean visibleActorTrackingActive = worldActive && worldMode.showsFog() && config.actorCutoutLimit().isEnabled();
		boolean debugActive = areaEnabled && config.debugOverlayEnabled();
		return new ComponentState(worldActive, minimapActive, debugActive, fadingWorldActive, fadingMinimapActive, fadingActive, overlayActive, visibleActorTrackingActive, anyConfigured);
	}
	private boolean isCurrentAreaEnabled(boolean sailing) {
		if (config.onlyInWilderness() && clientState.isNotInWilderness()) return false;
		if (config.disableWhileSailing() && sailing) return false;
		return !areaExclusionManager.isPlayerInExcludedArea();
	}
	private final class ToggleSpec {
		private final Overlay overlay;
		private final Predicate<ComponentState> activeFn;
		private boolean enabled;
		private ToggleSpec(Overlay overlay, Predicate<ComponentState> activeFn) {
			this.overlay = overlay;
			this.activeFn = activeFn;
		}
		private void update(ComponentState state) { set(activeFn.test(state)); }
		private void disable() { set(false); }
		private void set(boolean enabled) {
			if (this.enabled == enabled) return;
			if (enabled) overlayManager.add(overlay);
			else overlayManager.remove(overlay);
			this.enabled = enabled;
		}
	}
	private static final class LifecycleSpec {
		private final LifecycleComponent component;
		private final Predicate<ComponentState> activeFn;
		private LifecycleSpec(LifecycleComponent component, Predicate<ComponentState> activeFn) {
			this.component = component;
			this.activeFn = activeFn;
		}
		private void update(ComponentState state) {
			if (activeFn.test(state)) component.start();
			else component.stop();
		}
		private void stop() { component.stop(); }
	}
	private static final class ComponentState {
		private final boolean worldActive;
		private final boolean minimapActive;
		private final boolean debugActive;
		private final boolean fadingWorldActive;
		private final boolean fadingMinimapActive;
		private final boolean fadingActive;
		private final boolean overlayActive;
		private final boolean visibleActorTrackingActive;
		private final boolean anyConfigured;
		private ComponentState(boolean worldActive, boolean minimapActive, boolean debugActive, boolean fadingWorldActive, boolean fadingMinimapActive, boolean fadingActive, boolean overlayActive, boolean visibleActorTrackingActive, boolean anyConfigured) {
			this.worldActive = worldActive;
			this.minimapActive = minimapActive;
			this.debugActive = debugActive;
			this.fadingWorldActive = fadingWorldActive;
			this.fadingMinimapActive = fadingMinimapActive;
			this.fadingActive = fadingActive;
			this.overlayActive = overlayActive;
			this.visibleActorTrackingActive = visibleActorTrackingActive;
			this.anyConfigured = anyConfigured;
		}
	}
	@Provides
	@SuppressWarnings("unused")
	FogOfWarConfig provideConfig(ConfigManager configManager) {
		FogOfWarConfigMigration.migrate(configManager);
		return configManager.getConfig(FogOfWarConfig.class);
	}
}

package com.fogofwar.debug;
import com.fogofwar.config.FogOfWarConfig;
import com.fogofwar.coord.WorldEntityCoords;
import com.fogofwar.render.RenderCenterProvider;
import com.fogofwar.state.ClientState;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldEntityConfig;
import net.runelite.api.WorldView;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import javax.inject.Inject;
import java.awt.Dimension;
import java.awt.Graphics2D;
public class DebugOverlay extends OverlayPanel {
	private final Client client;
	private final FogOfWarConfig config;
	private final ClientState clientState;
	private final RenderCenterProvider renderCenterProvider;
	@Inject
	public DebugOverlay(Client client, FogOfWarConfig config, ClientState clientState, RenderCenterProvider renderCenterProvider) {
		this.client = client;
		this.config = config;
		this.clientState = clientState;
		this.renderCenterProvider = renderCenterProvider;
		setPosition(OverlayPosition.TOP_LEFT);
	}
	@Override
	public Dimension render(Graphics2D graphics) {
		if (!config.debugOverlayEnabled() || clientState.isClientNotReady()) return null;
		panelComponent.getChildren().clear();
		WorldView wv = getWorldView();
		WorldEntityConfig entityConfig = getWorldEntityConfig(wv);
		addLine("Current plane:", wv != null ? wv.getPlane() : "?");
		addLine("World view ID:", wv != null ? wv.getId() : "?");
		addLine("Entity ID:", entityConfig != null ? entityConfig.getId() : "?");
		addLine("Entity category:", entityConfig != null ? entityConfig.getCategory() : "?");
		return super.render(graphics);
	}
	private WorldView getWorldView() {
		Player localPlayer = client.getLocalPlayer();
		WorldView wv = localPlayer != null ? localPlayer.getWorldView() : null;
		if (wv == null) wv = renderCenterProvider.getTopLevelWorldView();
		return wv;
	}
	private WorldEntityConfig getWorldEntityConfig(WorldView worldView) {
		WorldEntity worldEntity = WorldEntityCoords.getWorldEntity(worldView, renderCenterProvider.getTopLevelWorldView());
		return worldEntity != null ? worldEntity.getConfig() : null;
	}
	private void addLine(String left, Object right) {
		panelComponent.getChildren().add(LineComponent.builder().left(left).right(String.valueOf(right)).build());
	}
}

package com.fogofwar.state;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.gameval.VarbitID;
import javax.inject.Inject;
import javax.inject.Singleton;
@Singleton
public class ClientState {
	private final Client client;
	@Inject
	public ClientState(Client client) { this.client = client; }
	public boolean isNotInWilderness() { return client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) != 1; }
	public boolean isSailing() { return client.getVarbitValue(VarbitID.SAILING_BOARDED_BOAT) == 1; }
	public boolean isClientNotReady() { return client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null; }
}

package com.fogofwar.coord;
import net.runelite.api.Actor;
import net.runelite.api.Player;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldEntityConfig;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
public final class WorldEntityCoords {
	private static final int SHIP_ENTITY_CATEGORY = 2395;
	private WorldEntityCoords() {}
	public static WorldEntity getWorldEntity(WorldView sourceWorldView, WorldView topWorldView) {
		if (sourceWorldView == null || topWorldView == null || sourceWorldView.isTopLevel()) return null;
		return topWorldView.worldEntities().byIndex(sourceWorldView.getId());
	}
	public static WorldEntity getPlayerWorldEntity(Player player, WorldView topWorldView) {
		if (player == null) return null;
		return getWorldEntity(player.getWorldView(), topWorldView);
	}
	public static WorldPoint toTopLevelWorldPoint(WorldView topWorldView, LocalPoint localPoint) {
		if (topWorldView == null || localPoint == null) return null;
		return WorldPoint.fromLocal(topWorldView, localPoint.getX(), localPoint.getY(), topWorldView.getPlane());
	}
	private static WorldEntity getPlayerShip(Player player, WorldView topWorldView) {
		WorldEntity worldEntity = getPlayerWorldEntity(player, topWorldView);
		return isShip(worldEntity) ? worldEntity : null;
	}
	public static boolean isPlayerOnShip(Player player, WorldView topWorldView) { return getPlayerShip(player, topWorldView) != null; }
	public static boolean isShip(WorldEntity worldEntity) {
		WorldEntityConfig config = worldEntity != null ? worldEntity.getConfig() : null;
		return config != null && config.getCategory() == SHIP_ENTITY_CATEGORY;
	}
	public static ResolvedPoint resolveTopLevel(Actor actor, WorldView topWorldView) { return resolveTopLevel(actor, null, topWorldView, null); }
	public static ResolvedPoint resolveTopLevel(Actor actor, WorldView sourceWorldView, WorldView topWorldView, WorldEntity worldEntity) {
		if (actor == null || topWorldView == null) return null;
		if (sourceWorldView == null) sourceWorldView = actor.getWorldView();
		if (sourceWorldView == null) return null;
		WorldPoint worldPoint = actor.getWorldLocation();
		LocalPoint localPoint = actor.getLocalLocation();
		if (sourceWorldView.isTopLevel()) {
			if (worldPoint == null) return null;
			if (localPoint == null) localPoint = LocalPoint.fromWorld(topWorldView, worldPoint);
			return localPoint != null ? new ResolvedPoint(worldPoint, localPoint) : null;
		}
		if (worldEntity == null) worldEntity = getWorldEntity(sourceWorldView, topWorldView);
		if (worldEntity == null) return null;
		if (localPoint == null && worldPoint != null) localPoint = LocalPoint.fromWorld(sourceWorldView, worldPoint);
		if (localPoint == null) return null;
		LocalPoint topLocalPoint = worldEntity.transformToMainWorld(localPoint);
		WorldPoint topWorldPoint = toTopLevelWorldPoint(topWorldView, topLocalPoint);
		return topWorldPoint != null ? new ResolvedPoint(topWorldPoint, topLocalPoint) : null;
	}
	public static WorldPoint playerToTopLevel(Player player, WorldView sourceWorldView, WorldView topWorldView) {
		ResolvedPoint point = resolveTopLevel(player, sourceWorldView, topWorldView, null);
		return point != null ? point.worldPoint : null;
	}
	public static final class ResolvedPoint {
		public final WorldPoint worldPoint;
		public final LocalPoint localPoint;
		private ResolvedPoint(WorldPoint worldPoint, LocalPoint localPoint) {
			this.worldPoint = worldPoint;
			this.localPoint = localPoint;
		}
	}
}
